// Photo asset "pa" — added by the builder (their own real, local image).
// Use it in any page with:
//   <script src="./assets/pa.js"></script>
//   <img data-asset="pa" alt="describe the photo">
window.ASSETS = Object.assign(window.ASSETS || {}, { "pa": "data:image/jpeg;base64," });
(function () {
  function apply() { document.querySelectorAll('img[data-asset="pa"]').forEach(function (img) { img.src = window.ASSETS["pa"]; }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();
